//
//  PersistentCodableStore.swift
//  SwiftMandarin
//
//  Shared loader/saver for the app's UserDefaults-backed JSON stores
//  (vocabulary, history, learning progress, activity). Decode failures are
//  logged instead of silently discarded, and a last-known-good snapshot is
//  kept under "<key>.backup" so a corrupted payload can't wipe user data.
//

import Foundation
import os.log

enum PersistentCodableStore {

    private static let log = Logger(subsystem: "com.rogerlin.SwiftMandarin", category: "Persistence")

    /// Load and decode the value stored under `key`.
    ///
    /// On a successful decode the payload is also snapshotted to
    /// "<key>.backup" (once per launch is enough — this is called from each
    /// store's init). If the primary payload fails to decode, the backup is
    /// tried; when the backup succeeds it is promoted back to the primary key.
    static func load<T: Codable>(_ type: T.Type, key: String) -> T? {
        let defaults = UserDefaults.standard
        let backupKey = key + ".backup"

        if let data = defaults.data(forKey: key) {
            do {
                let value = try JSONDecoder().decode(T.self, from: data)
                defaults.set(data, forKey: backupKey)
                return value
            } catch {
                log.error("Decode failed for \(key, privacy: .public): \(error.localizedDescription, privacy: .public) — trying backup")
            }
        }

        if let backup = defaults.data(forKey: backupKey) {
            do {
                let value = try JSONDecoder().decode(T.self, from: backup)
                log.notice("Restored \(key, privacy: .public) from last-known-good backup")
                defaults.set(backup, forKey: key)
                return value
            } catch {
                log.error("Backup decode also failed for \(key, privacy: .public): \(error.localizedDescription, privacy: .public)")
            }
        }

        return nil
    }

    /// Encode and store `value` under `key`, logging encode failures
    /// (which would otherwise silently skip the write).
    static func save<T: Codable>(_ value: T, key: String) {
        do {
            let data = try JSONEncoder().encode(value)
            UserDefaults.standard.set(data, forKey: key)
        } catch {
            log.error("Encode failed for \(key, privacy: .public): \(error.localizedDescription, privacy: .public)")
        }
    }
}

//
//  SavedTerm.swift
//  SwiftMandarin
//
//  Model for saved vocabulary terms
//

import Foundation
import SwiftUI
import Observation

struct SavedTerm: Identifiable, Codable, Equatable, Hashable {
    let id: UUID
    let chinese: String
    let pinyin: String
    let definition: String
    let partOfSpeech: String
    let dateAdded: Date
    var sortOrder: Int
    var isMastered: Bool

    init(
        id: UUID = UUID(),
        chinese: String,
        pinyin: String,
        definition: String,
        partOfSpeech: String = "",
        dateAdded: Date = Date(),
        sortOrder: Int = 0,
        isMastered: Bool = false
    ) {
        self.id = id
        self.chinese = chinese
        self.pinyin = pinyin
        self.definition = definition
        self.partOfSpeech = partOfSpeech
        self.dateAdded = dateAdded
        self.sortOrder = sortOrder
        self.isMastered = isMastered
    }
}

// MARK: - Interface-language-aware display

/// The `chinese` field is really a *headword*: photo-extraction and workbook
/// flows store English headwords there when the user is learning English. So
/// the two display sides are detected from content, and which side is the big
/// headline follows the interface language (= the user's native language):
/// 中文 UI → learning English → English is the headline, Mandarin the gloss;
/// English UI → learning Mandarin → Chinese headline + pinyin, English gloss.
extension SavedTerm {

    /// The Chinese side of the entry (headword preferred, else definition).
    var chineseSide: String {
        if chinese.containsCJK { return chinese }
        if definition.containsCJK { return definition }
        return ""
    }

    /// The English side of the entry (headword preferred, else definition).
    var englishSide: String {
        if !chinese.containsCJK, !chinese.isEmpty { return chinese }
        if !definition.containsCJK { return definition }
        return ""
    }

    /// The text shown big — the side in the language the user is learning.
    /// Falls back to the headword when the entry has no text in that language.
    @MainActor
    var headlineText: String {
        let primary = LocalizationManager.shared.learningIsChinese ? chineseSide : englishSide
        return primary.isEmpty ? chinese : primary
    }

    /// The small secondary text — the side in the user's native language.
    /// Empty when the entry has nothing beyond the headline.
    @MainActor
    var glossText: String {
        let secondary = LocalizationManager.shared.learningIsChinese ? englishSide : chineseSide
        return secondary == headlineText ? "" : secondary
    }

    /// Pinyin is a learner aid for reading Chinese: shown only when the user
    /// is learning Chinese (English UI) and the entry has a Chinese side.
    @MainActor
    var showsPinyin: Bool {
        LocalizationManager.shared.learningIsChinese && !chineseSide.isEmpty && !pinyin.isEmpty
    }
}

